
CREATE TABLE "modifiers" (
  "col1" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "col2" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "col3" NUMBER(10) NOT NULL PRIMARY KEY,
  "col4" NUMBER(10) NOT NULL,
  "col5" NUMBER(10) NOT NULL DEFAULT 0,
  "col6" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "col7" NUMBER(10) NOT NULL PRIMARY KEY,
  "col8" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "col9" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
